# Greedy
class Solution(object):
    def monotoneIncreasingDigits(self, N):
        """
        :type N: int
        :rtype: int
        """
        str_num = list(str(N))
        n = len(str_num)
        flag = -1
        for i in range(n - 1, 0, -1):
            if str_num[i - 1] > str_num[i]:
                flag = i
                str_num[i - 1] = chr(ord(str_num[i - 1]) - 1)
        if flag != -1:
            for i in range(flag, n):
                str_num[i] = '9'
        return int("".join(str_num))
